window.HeadChat=(()=>{
 let messages=[],busy=false,error='',context;
 const escapeHTML=value=>String(value).replace(/[&<>"']/g,c=>({'&':'&amp;','<':'&lt;','>':'&gt;','"':'&quot;',"'":'&#39;'}[c]));
 function markup(){return `<div class="head-title"><h2>Security AI assistant</h2><span class="head-tag">Live chat</span></div><p class="hint">Ask a question or continue a conversation. Answers about activity use the selected records.</p><div class="chat-thread" id="head-chat-thread" role="log" aria-live="polite">${messages.length?messages.map(m=>`<article class="chat-message ${m.role}"><strong>${m.role==='user'?'You':'Amrita assistant'}</strong><p>${escapeHTML(m.content)}</p></article>`).join(''):'<article class="chat-message assistant"><strong>Amrita assistant</strong><p>Hello! Ask me about gate operations, today’s activity, inspection queues or another question.</p></article>'}${busy?'<div class="chat-thinking" role="status">Assistant is replying…</div>':''}</div>${error?`<p class="chat-error" role="alert">${escapeHTML(error)}</p>`:''}<form id="head-chat-form"><label class="field">Your message<textarea id="head-chat-input" required maxlength="2000" rows="2" placeholder="Ask anything…" ${busy?'disabled':''}></textarea></label><div class="actions"><button class="btn" ${busy?'disabled':''}>${busy?'Replying…':'Send message →'}</button><button type="button" class="btn secondary" id="head-chat-clear" ${busy?'disabled':''}>New conversation</button></div></form><p class="hint">Your messages and aggregate activity summaries are sent to the AI provider. Avoid private visitor details. The assistant cannot change permissions or records.</p>`;}
 function paint(){const panel=document.querySelector('#head-chat-panel');if(panel){panel.innerHTML=markup();bind();const thread=document.querySelector('#head-chat-thread');thread.scrollTop=thread.scrollHeight;}}
 function bind(){const form=document.querySelector('#head-chat-form');if(!form)return;form.onsubmit=async e=>{e.preventDefault();if(busy)return;const text=document.querySelector('#head-chat-input').value.trim();if(!text)return;messages.push({role:'user',content:text});busy=true;error='';const payload={model:'openai/gpt-oss-20b',messages:messages.slice(-9).map(m=>({role:m.role,content:m.content.slice(0,2000)})),context:context()};paint();try{const r=await fetch('/api/ai/chat',{method:'POST',headers:{'Content-Type':'application/json'},body:JSON.stringify(payload)});const data=await r.json();if(!r.ok)throw Error(data.error||'Unable to get a reply');if(typeof data.reply!=='string')throw Error('Invalid assistant response');messages.push({role:'assistant',content:data.reply});}catch(e){error='Message could not be answered: '+e.message+' Please try again.';}finally{busy=false;paint();}};document.querySelector('#head-chat-clear').onclick=()=>{messages=[];error='';paint();};document.querySelector('#head-chat-input').onkeydown=e=>{if(e.key==='Enter'&&!e.shiftKey){e.preventDefault();form.requestSubmit();}};}
 return {markup,attach(getContext){context=getContext;bind();}};
})();
